SELECT id, log_ts, level, status_code, context, context['version'] AS version, COALESCE(context['trace'], 'none') AS trace_or_default, COALESCE(context['region'], 'direct') AS region_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace FROM app_logs WHERE status_code != 424;
